// 「裏・ブリージーチェリーブロッサム」
// Source: st06bs.ecl.txt BossCard6:1574-1673 and its dependencies
//         BossCard6_at:1675-1707, _at2:1709-1753, _at3:1755-1802,
//         _at4:1804-1828, _at4b:1830-1872, _at_f:1874-1913.
// Approved aliases of identical TH16/TH18 type slots (bullet-types.md, 2026-11-07).
const TH16_BALL: int = 416;        // source type 4
const TH16_RING_BALL2: int = 464;  // source type 7
const TH16_RICE: int = 480;        // source type 8
const TH16_BIG_BALL2: int = 656;   // source type 19
const TH16_GLOW_BALL: int = 880;   // source type 33

const TIME_LIMIT: int = 7324;      // 120 shell buffer + 7200 source window + 4 startup
const OPENING_BUFFER: int = 120;

// Same-enemy shared slots for the source killAsync(N)+re-async at phase changes.
const SLOT_GEN2: int = 0;
const SLOT_GEN3: int = 1;

// Source at_f step C = +-3.883222 rad = +-222.5 deg.
const AT_F_STEP_P: int = 40504;
const AT_F_STEP_N: int = -40504;

// BossCard6_at3 EX type 8 (ANGLE_ACCEL): a=120, r=0, s=+-0.0052359877 rad/frame
// (0.3 deg/frame ~= 55 BAM/frame).
xformdef SPIN120(omega: angle) {
    set_ang_vel(omega);
    wait(120);
    set_ang_vel(0deg);
}

// BossCard6_at4/at4b EX type 2097152 (VELTIME): a=60, r=3.0, angle kept.
// Config speed 0.1 -> 3.0 over 60 frames, direction fixed at spawn.
xformdef RAMP_60 {
    set_accel(0.0483333fx);
    wait(60);
    set_accel(0fx);
}

// BossCard6_at_f: EX WAIT a=120+2*g (slot 1 rewritten per wave) then the same
// 60-frame VELTIME ramp.
xformdef RICE_RAMP(w: int) {
    wait(w);
    set_accel(0.0483333fx);
    wait(60);
    set_accel(0fx);
}

// BossCard6 (1590-1673): phase manager. Source $LIFE stays at the scripted 5000
// because the shell never applies player damage, so the $LIFE>3500/2500/1500
// halves of the conditions never fail; phases advance on $TIME (30/60/90 s).
async sub boss_main() {
    set_invuln(65535);
    set_hitbox(25fx);   // Boss() context setHitbox(50,50) -> source radius 25
    set_hurtbox(28fx);  // Boss() context setHurtbox(56,56) -> source radius 28
    set_self_int(SLOT_GEN2, 0);
    set_self_int(SLOT_GEN3, 0);
    // 1615 movePosTime(60, 4, 0.0, 128.0): already at (0,128) after Boss6.
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(90);  // "+90:" block (moveLimit/bombInvuln/funcSet(2) omitted)
    spawn at_move();  // 1625 @BossCard6_at() async 1
    while $self_age <= 1800 { wait(1); }  // 1630 $LIFE>3500 && $TIME<=30*60
    play_clear();
    set_self_int(SLOT_GEN2, 1);
    spawn at2(1);  // 1633 @BossCard6_at2() async 2
    while $self_age <= 3600 { wait(1); }  // 1638
    play_clear();
    set_self_int(SLOT_GEN2, 2);
    set_self_int(SLOT_GEN3, 1);
    spawn at2(2);  // 1642 killAsync(2); @BossCard6_at2() async 2
    spawn at3(1);  // 1643 @BossCard6_at3() async 3
    while $self_age <= 5400 { wait(1); }  // 1648
    play_clear();
    set_self_int(SLOT_GEN2, 3);
    set_self_int(SLOT_GEN3, 2);
    spawn at2(3);  // 1654
    spawn at3(2);  // 1655
    spawn at4();   // 1656
    if global(GVAR_RANK) == 0 {
        spawn at4b();  // 1658 !NHL @BossCard6_at4b() async 5
    }
    loop { wait(1); }  // 1660-1671 endless tail until the 7200 timeout
}

// Source 1632/1640/1650 etClear(640.0): keep the in-attack bullet wipe.
sub play_clear() {
    clear_bullets_at($self_x, $self_y, 640fx, 0);
}

// BossCard6_at (1675-1707): hexagram walk; each segment fires one at_f burst.
async sub at_move() {
    wait(60);
    loop {
        at_f(AT_F_STEP_P as angle);
        wait(60);
        move_to(120, 64fx, 96fx, EASE_QUAD_IN);  // 1682 movePosTime(120,1,64,96)
        wait(120);
        at_f(AT_F_STEP_N as angle);
        wait(60);
        move_to(120, 128fx, 128fx, EASE_QUAD_IN);  // 1686
        wait(120);
        at_f(AT_F_STEP_P as angle);
        wait(60);
        move_to(120, 0fx, 144fx, EASE_QUAD_IN);  // 1690
        wait(120);
        at_f(AT_F_STEP_N as angle);
        wait(60);
        move_to(120, -128fx, 128fx, EASE_QUAD_IN);  // 1694
        wait(120);
        at_f(AT_F_STEP_P as angle);
        wait(60);
        move_to(120, -64fx, 96fx, EASE_QUAD_IN);  // 1698
        wait(120);
        at_f(AT_F_STEP_N as angle);
        wait(60);
        move_to(120, 0fx, 128fx, EASE_QUAD_IN);  // 1702
        wait(120);
    }
}

// BossCard6_at_f (1874-1913): sprite type8/color4, aim mode3, 7 ways, 1 layer,
// speed 0.1, WAIT(120+2g) then VELTIME(60, 3.0). One 7-way wave per frame for
// diffI(H) frames; base angle starts at RANDRAD and advances by `step` per wave;
// etDist f = 4*g along each bullet angle.
sub at_f(step: angle) {
    var e: angle = rand(65536) as angle;
    var f: fx = 0fx;
    var h: int = 40;
    var r: int = global(GVAR_RANK);
    if r == 2 { h = 50; }
    if r == 3 { h = 60; }
    var g: int = 0;
    while g < h {
        var w: int = 120 + g * 2;
        var d: fx = f - 0.4fx;  // etDist f + ANIM displacement -4*0.1
        for i in 0..7 {
            var ang: angle = e + (((i * 65536) / 7) as angle);
            _ = fire(TH16_RICE, 4,
                     $self_x + d * cos(ang), $self_y + d * sin(ang),
                     0.1fx, ang, RICE_RAMP(w), none);
        }
        e = e + step;
        f = f + 4fx;
        g = g + 1;
        wait(1);
    }
}

// BossCard6_at2 (1709-1753): one bullet per wave from an absolute field point
// (etOffsetAbs x=RANDF2*192, y=0), angle 90deg + RANDF2*10deg, speed random.
// interval E16/N4/H3/L3; speed E/N 1.0+U*1.0, H 1.4+U*1.4, L 1.5+U*1.5.
async sub at2(gen: int) {
    var spd_lo: fx = 1.0fx;
    var spd_span: fx = 1.0fx;
    var every: int = 16;
    var r: int = global(GVAR_RANK);
    if r == 1 { every = 4; }
    if r == 2 { every = 3; spd_lo = 1.4fx; spd_span = 1.4fx; }
    if r == 3 { every = 3; spd_lo = 1.5fx; spd_span = 1.5fx; }
    loop {
        if self_int(SLOT_GEN2) != gen { return; }
        var r1: int = rand(65536);
        var u1: fx = (r1 - 32768) as fx / 32768;
        var ox: fx = u1 * 192fx;
        var r2: int = rand(65536);
        var u2: fx = (r2 - 32768) as fx / 32768;
        var off: int = (u2 * 1820fx) as int;
        var a: angle = 90deg + (off as angle);
        var r3: int = rand(65536);
        var u3: fx = (r3 - 32768) as fx / 65536 + 0.5fx;
        var spd: fx = spd_lo + u3 * spd_span;
        var bx: fx = ox - 4fx * spd * cos(a);  // ANIM displacement -4*velocity
        var by: fx = 0fx - 4fx * spd * sin(a);
        _ = fire(TH16_RING_BALL2, 4, bx, by, spd, a, none, none);
        wait(every);
    }
}

// BossCard6_at3 (1755-1802): 8-way half-offset ring (mode5), sprite 19/2,
// speed 1.2+U*0.5 per wave, ANGLE_ACCEL 120 frames with alternating sign.
// interval E120/N40/H30/L20.
async sub at3(gen: int) {
    var every: int = 120;
    var r: int = global(GVAR_RANK);
    if r == 1 { every = 40; }
    if r == 2 { every = 30; }
    if r == 3 { every = 20; }
    var sgn: int = 1;
    loop {
        if self_int(SLOT_GEN3) != gen { return; }
        var rr: int = rand(65536);
        var u: fx = (rr - 32768) as fx / 65536 + 0.5fx;
        var spd: fx = 1.2fx + u * 0.5fx;
        var omega: angle = 55bam;
        if sgn < 0 { omega = -55bam; }
        sgn = -sgn;
        for i in 0..8 {
            var ang: angle = 90deg + 4096bam + (((i * 65536) / 8) as angle);
            var d: fx = 0fx - 4fx * spd;  // ANIM displacement -4*velocity
            _ = fire(TH16_BIG_BALL2, 2,
                     $self_x + d * cos(ang), $self_y + d * sin(ang),
                     spd, ang, SPIN120(omega), none);
        }
        wait(every);
    }
}

// BossCard6_at4 (1804-1828): 16-way half-offset ring (mode5), sprite 33/1,
// config speed 0.1, VELTIME(60, 3.0) with angle kept. One wave per 90 frames.
async sub at4() {
    loop {
        for i in 0..16 {
            var ang: angle = 90deg + 2048bam + (((i * 65536) / 16) as angle);
            var d: fx = 0fx - 0.4fx;  // ANIM displacement -4*0.1
            _ = fire(TH16_GLOW_BALL, 1,
                     $self_x + d * cos(ang), $self_y + d * sin(ang),
                     0.1fx, ang, RAMP_60, none);
        }
        wait(90);
    }
}

// BossCard6_at4b (1830-1872, Easy only): mode5 ring sprite 4/2, 48 ways (E),
// speed 0.1 + VELTIME(60, 3.0); interval 90 (E) / 60 (others).
async sub at4b() {
    var n: int = 48;
    var every: int = 90;
    if global(GVAR_RANK) != 0 { n = 64; every = 60; }
    var half: int = 65536 / (2 * n);
    loop {
        for i in 0..n {
            var ang: angle = 90deg + (half as angle) + (((i * 65536) / n) as angle);
            var d: fx = 0fx - 0.4fx;
            _ = fire(TH16_BALL, 2,
                     $self_x + d * cos(ang), $self_y + d * sin(ang),
                     0.1fx, ang, RAMP_60, none);
        }
        wait(every);
    }
}

// Validation shell (validation.md): control owns the phase, no body contact;
// the real source enemy keeps boxes, movement and firing.
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 5000, 0, 0, 0, boss_main);  // Boss6 lifeSet(5000)
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
